import itertools

def solve_puzzle():
    positions = list(range(1, 6))
    people = ['Blake', 'Casey', 'Harper', 'Morgan', 'Sawyer']
    colors = ['blue', 'green', 'orange', 'red', 'yellow']
    pets = ['bird', 'dog', 'fish', 'horse', 'rabbit']
    drinks = ['cocoa', 'coffee', 'juice', 'milk', 'tea']
    hobbies = ['baking', 'fencing', 'hiking', 'painting', 'rowing']

    solutions = []

    for person_perm in itertools.permutations(people):
        for color_perm in itertools.permutations(colors):
            for pet_perm in itertools.permutations(pets):
                for drink_perm in itertools.permutations(drinks):
                    for hobby_perm in itertools.permutations(hobbies):
                        # Create assignment: position -> attributes
                        assignment = {}
                        for i in range(5):
                            pos = i + 1
                            assignment[pos] = {
                                'person': person_perm[i],
                                'color': color_perm[i],
                                'pet': pet_perm[i],
                                'drink': drink_perm[i],
                                'hobby': hobby_perm[i]
                            }

                        if check_all_clues(assignment):
                            solutions.append(assignment)

    return solutions

def check_all_clues(assignment):
    """Check all 16 clues"""
    def find_pos_by(attr, value):
        for pos in range(1, 6):
            if assignment[pos][attr] == value:
                return pos
        return -1

    def adjacent(pos1, pos2):
        return abs(pos1 - pos2) == 1

    # Clue 1: Orange house person ≠ painting
    orange_pos = find_pos_by('color', 'orange')
    if orange_pos > 0 and assignment[orange_pos]['hobby'] == 'painting':
        return False

    # Clue 2: Horse owner ≠ Blake
    horse_pos = find_pos_by('pet', 'horse')
    if horse_pos > 0 and assignment[horse_pos]['person'] == 'Blake':
        return False

    # Clue 3: Blue house immediately left of Sawyer
    sawyer_pos = find_pos_by('person', 'Sawyer')
    blue_pos = find_pos_by('color', 'blue')
    if blue_pos > 0 and sawyer_pos > 0 and blue_pos != sawyer_pos - 1:
        return False

    # Clue 4: Casey next to hiking person
    casey_pos = find_pos_by('person', 'Casey')
    hiking_pos = find_pos_by('hobby', 'hiking')
    if casey_pos > 0 and hiking_pos > 0 and not adjacent(casey_pos, hiking_pos):
        return False

    # Clue 5: Baking immediately left of tea
    baking_pos = find_pos_by('hobby', 'baking')
    tea_pos = find_pos_by('drink', 'tea')
    if baking_pos > 0 and tea_pos > 0 and baking_pos + 1 != tea_pos:
        return False

    # Clue 6: Baking immediately left of dog owner
    dog_pos = find_pos_by('pet', 'dog')
    if baking_pos > 0 and dog_pos > 0 and baking_pos + 1 != dog_pos:
        return False

    # Clue 7: Rabbit owner next to fencing person
    rabbit_pos = find_pos_by('pet', 'rabbit')
    fencing_pos = find_pos_by('hobby', 'fencing')
    if rabbit_pos > 0 and fencing_pos > 0 and not adjacent(rabbit_pos, fencing_pos):
        return False

    # Clue 8: Tea drinker next to horse owner
    if tea_pos > 0 and horse_pos > 0 and not adjacent(tea_pos, horse_pos):
        return False

    # Clue 9: Casey next to bird owner
    bird_pos = find_pos_by('pet', 'bird')
    if casey_pos > 0 and bird_pos > 0 and not adjacent(casey_pos, bird_pos):
        return False

    # Clue 10: Red house next to rabbit owner
    red_pos = find_pos_by('color', 'red')
    if red_pos > 0 and rabbit_pos > 0 and not adjacent(red_pos, rabbit_pos):
        return False

    # Clue 11: Cocoa drinker next to orange house
    cocoa_pos = find_pos_by('drink', 'cocoa')
    if cocoa_pos > 0 and orange_pos > 0 and not adjacent(cocoa_pos, orange_pos):
        return False

    # Clue 12: Yellow house person does rowing
    yellow_pos = find_pos_by('color', 'yellow')
    rowing_pos = find_pos_by('hobby', 'rowing')
    if yellow_pos > 0 and rowing_pos > 0 and yellow_pos != rowing_pos:
        return False

    # Clue 13: Bird owner is Harper
    if bird_pos > 0 and assignment[bird_pos]['person'] != 'Harper':
        return False

    # Clue 14: Sawyer drinks juice
    if sawyer_pos > 0 and assignment[sawyer_pos]['drink'] != 'juice':
        return False

    # Clue 15: Blue house immediately left of painting person
    painting_pos = find_pos_by('hobby', 'painting')
    if blue_pos > 0 and painting_pos > 0 and blue_pos != painting_pos - 1:
        return False

    # Clue 16: Bird owner drinks milk
    if bird_pos > 0 and assignment[bird_pos]['drink'] != 'milk':
        return False

    return True

solutions = solve_puzzle()

print(f"Found {len(solutions)} solution(s)\n")

if solutions:
    sol = solutions[0]
    print("Solution:")
    for pos in range(1, 6):
        print(f"Position {pos}: {sol[pos]}")

    # Find bird owner
    bird_pos = -1
    for pos in range(1, 6):
        if sol[pos]['pet'] == 'bird':
            bird_owner = sol[pos]['person']
            break

    print(f"\nBird owner: {bird_owner}")
